cat > /tmp/test_thresholds.mjs << 'EOF'
import { Eval } from './packages/frai-core/src/eval/index.js';

console.log('Testing threshold implementation...\n');

const mockEvaluations = [
  { id: 'exact_match', label: 'Exact Match', score: 0.95, total: 20, matches: 19 },
  { id: 'toxicity', label: 'Toxicity', score: 0.02, total: 20, flagged: 1 }
];

console.log('Test 1: Thresholds pass');
try {
  const report1 = Eval.generateReport({
    evaluations: mockEvaluations,
    thresholds: { exact_match: 0.9, toxicity: 0.05 }
  });
  console.log('  passed:', report1.passed);
  console.log('  thresholds:', JSON.stringify(report1.thresholds, null, 2));
  console.log('  ✓ PASS\n');
} catch (e) {
  console.log('  ✗ FAIL:', e.message, '\n');
}

console.log('Test 2: Threshold fails');
try {
  const report2 = Eval.generateReport({
    evaluations: mockEvaluations,
    thresholds: { exact_match: 0.99 }
  });
  console.log('  passed:', report2.passed);
  console.log('  thresholds:', JSON.stringify(report2.thresholds, null, 2));
  console.log('  ✓ PASS\n');
} catch (e) {
  console.log('  ✗ FAIL:', e.message, '\n');
}

console.log('Test 3: Metric with null score');
try {
  const report3 = Eval.generateReport({
    evaluations: [
      { id: 'exact_match', label: 'Exact Match', score: null, total: 0, matches: 0 }
    ],
    thresholds: { exact_match: 0.5 }
  });
  console.log('  passed:', report3.passed);
  console.log('  thresholds:', JSON.stringify(report3.thresholds, null, 2));
  console.log('  ✓ PASS\n');
} catch (e) {
  console.log('  ✗ FAIL:', e.message, '\n');
}

console.log('Test 4: Unknown metric (should throw)');
try {
  const report4 = Eval.generateReport({
    evaluations: mockEvaluations,
    thresholds: { unknown_metric: 0.5 }
  });
  console.log('  ✗ FAIL: Should have thrown error\n');
} catch (e) {
  if (e.message.includes('Unknown metric')) {
    console.log('  Error:', e.message);
    console.log('  ✓ PASS\n');
  } else {
    console.log('  ✗ FAIL: Wrong error:', e.message, '\n');
  }
}

console.log('Test 5: No thresholds (backwards compat)');
try {
  const report5 = Eval.generateReport({
    evaluations: mockEvaluations
  });
  const hasPassed = 'passed' in report5;
  const hasThresholds = 'thresholds' in report5;
  console.log('  has passed field:', hasPassed);
  console.log('  has thresholds field:', hasThresholds);
  if (!hasPassed && !hasThresholds) {
    console.log('  ✓ PASS\n');
  } else {
    console.log('  ✗ FAIL: Should not have new fields\n');
  }
} catch (e) {
  console.log('  ✗ FAIL:', e.message, '\n');
}

console.log('All threshold implementation tests completed!');
EOF
node /tmp/test_thresholds.mjs
